/**
 * @name Unsafe attribute access with external input
 * @description Dynamic attribute access (getattr/setattr) where attribute name could be controlled by external input
 * @kind path-problem
 * @problem.severity error
 * @id py/unsafe-attribute-access-taint
 * @tags security
 *        external/cwe/cwe-915
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module UnsafeAttrConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    // Function parameters that could be externally controlled
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::builtin("getattr").getACall() or
        call = API::builtin("setattr").getACall() or
        call = API::builtin("hasattr").getACall()
      ) and
      sink = call.getArg(1)  // The attribute name argument
    )
  }
}

module UnsafeAttrFlow = TaintTracking::Global<UnsafeAttrConfig>;
import UnsafeAttrFlow::PathGraph

from UnsafeAttrFlow::PathNode source, UnsafeAttrFlow::PathNode sink
where UnsafeAttrFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Attribute name flows from external parameter $@ to dynamic attribute access.", source.getNode(), "here"

/**
 * @name Regular expression injection
 * @description User-controlled data used in regular expression compilation could lead to ReDoS
 * @kind path-problem
 * @problem.severity warning
 * @id py/regex-injection
 * @tags security
 *        external/cwe/cwe-730
 *        external/cwe/cwe-400
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module RegexInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("re").getMember(["compile", "match", "search", "findall", "finditer", "sub", "subn", "split"]).getACall() or
        call = API::builtin("compile").getACall()
      ) and
      sink = call.getArg(0)
    )
  }
}

module RegexInjectionFlow = TaintTracking::Global<RegexInjectionConfig>;
import RegexInjectionFlow::PathGraph

from RegexInjectionFlow::PathNode source, RegexInjectionFlow::PathNode sink
where RegexInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Regular expression pattern derived from user input $@.", source.getNode(), "here"
